package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDate;
@Entity@Table(name="spms_commitment_item",uniqueConstraints=@UniqueConstraint(name="uk_spms_commitment_item_order",columnNames={"agency_id","commitment_section_id","display_order"}))public class PerformanceCommitmentItem extends RspAuditedEntity{@Column(name="commitment_version_id",nullable=false,length=36)private String commitmentVersionId;@Column(name="commitment_section_id",nullable=false,length=36)private String commitmentSectionId;@Column(name="source_item_id",nullable=false,length=36)private String sourceItemId;@Column(name="indicator_version_id",nullable=false,length=36)private String indicatorVersionId;@Column(nullable=false,length=200)private String label;@Column(name="output_description",nullable=false,length=2000)private String outputDescription;@Column(name="key_result_area",nullable=false,length=500)private String keyResultArea;@Column(name="performance_indicator",nullable=false,length=1000)private String performanceIndicator;@Column(name="success_statement",nullable=false,length=2000)private String successStatement;@Column(name="measure_type",nullable=false,length=30)private String measureType;@Column(name="unit_of_measure",nullable=false,length=100)private String unitOfMeasure;@Column(nullable=false,length=30)private String direction;@Column(name="weight_percent",nullable=false,precision=7,scale=4)private BigDecimal weightPercent;@Column(name="required_item",nullable=false)private boolean required;@Column(name="source_requires_evidence",nullable=false)private boolean sourceRequiresEvidence;@Column(name="source_evidence_requirement",length=2000)private String sourceEvidenceRequirement;@Column(name="indicator_fingerprint",nullable=false,length=64)private String indicatorFingerprint;@Column(name="committed_value",precision=19,scale=6)private BigDecimal committedValue;@Column(name="committed_from",precision=19,scale=6)private BigDecimal committedFrom;@Column(name="committed_to",precision=19,scale=6)private BigDecimal committedTo;@Column(name="target_start")private LocalDate targetStart;@Column(name="target_end")private LocalDate targetEnd;@Column(name="deliverable_clarification",length=2000)private String deliverableClarification;@Column(name="responsible_employee_id")private Long responsibleEmployeeId;@Column(name="responsible_employee_no",length=100)private String responsibleEmployeeNo;@Column(name="responsible_name",length=300)private String responsibleName;@Column(name="responsible_fingerprint",length=64)private String responsibleFingerprint;@Column(name="planning_remarks",length=2000)private String planningRemarks;@Column(name="evidence_clarification",length=2000)private String evidenceClarification;@Column(name="display_order",nullable=false)private int displayOrder;protected PerformanceCommitmentItem(){}public PerformanceCommitmentItem(String a,String v,String section,PerformanceTemplateItem item,PerformanceSuccessIndicatorVersion indicator,String fp){super(a);commitmentVersionId=v;commitmentSectionId=section;sourceItemId=item.getId();indicatorVersionId=indicator.getId();label=item.getLabelOverride()==null?indicator.getTitle():item.getLabelOverride();outputDescription=indicator.getOutputDescription();keyResultArea=indicator.getKeyResultArea();performanceIndicator=indicator.getPerformanceIndicator();successStatement=indicator.getSuccessStatement();measureType=indicator.getMeasureType().name();unitOfMeasure=indicator.getUnitOfMeasure();direction=indicator.getDirection().name();weightPercent=item.getWeightPercent();required=item.isRequired();sourceRequiresEvidence=indicator.isRequiresEvidence();sourceEvidenceRequirement=item.getEvidenceOverride()==null?indicator.getEvidenceRequirements():item.getEvidenceOverride();indicatorFingerprint=fp;committedValue=indicator.getTargetValue();committedFrom=indicator.getTargetFrom();committedTo=indicator.getTargetTo();displayOrder=item.getDisplayOrder();}public void target(BigDecimal value,BigDecimal from,BigDecimal to,LocalDate start,LocalDate end,String deliverable,Long employee,String no,String name,String fp,String remarks,String evidence){committedValue=value;committedFrom=from;committedTo=to;targetStart=start;targetEnd=end;deliverableClarification=optionalText(deliverable);responsibleEmployeeId=employee;responsibleEmployeeNo=optionalText(no);responsibleName=optionalText(name);responsibleFingerprint=optionalText(fp);planningRemarks=optionalText(remarks);evidenceClarification=optionalText(evidence);}public String getCommitmentVersionId(){return commitmentVersionId;}public String getCommitmentSectionId(){return commitmentSectionId;}public String getSourceItemId(){return sourceItemId;}public String getIndicatorVersionId(){return indicatorVersionId;}public String getLabel(){return label;}public String getOutputDescription(){return outputDescription;}public String getKeyResultArea(){return keyResultArea;}public String getPerformanceIndicator(){return performanceIndicator;}public String getSuccessStatement(){return successStatement;}public String getMeasureType(){return measureType;}public String getUnitOfMeasure(){return unitOfMeasure;}public String getDirection(){return direction;}public BigDecimal getWeightPercent(){return weightPercent;}public boolean isRequired(){return required;}public boolean isSourceRequiresEvidence(){return sourceRequiresEvidence;}public String getSourceEvidenceRequirement(){return sourceEvidenceRequirement;}public String getIndicatorFingerprint(){return indicatorFingerprint;}public BigDecimal getCommittedValue(){return committedValue;}public BigDecimal getCommittedFrom(){return committedFrom;}public BigDecimal getCommittedTo(){return committedTo;}public LocalDate getTargetStart(){return targetStart;}public LocalDate getTargetEnd(){return targetEnd;}public String getDeliverableClarification(){return deliverableClarification;}public Long getResponsibleEmployeeId(){return responsibleEmployeeId;}public String getResponsibleEmployeeNo(){return responsibleEmployeeNo;}public String getResponsibleName(){return responsibleName;}public String getResponsibleFingerprint(){return responsibleFingerprint;}public String getPlanningRemarks(){return planningRemarks;}public String getEvidenceClarification(){return evidenceClarification;}public int getDisplayOrder(){return displayOrder;}}
